//! Persistent download state (records, settings, trash), stored as JSON
//! under the app data directory.
use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

/// One download segment ("chunk" / "connection").
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ChunkRec {
    /// Registry record id.
    pub id: u32,
    /// Byte offset in the final file where this chunk starts (inclusive).
    pub start: u64,
    /// Byte offset where this chunk ends (exclusive).
    pub end: u64,
    /// Connection index that owns it (`conn=%ld`).
    pub conn: u32,
    /// Contiguous bytes already downloaded from `start` (`dwnl` in dumps).
    pub downloaded: u64,
    /// Chunk finished (`isCompl=%ld`).
    pub is_compl: bool,
    /// Unix timestamp when the chunk started downloading (`sttm=%ld`).
    pub sttm: i64,
    /// Unix timestamp when the chunk finished (`etm=%ld`).
    pub etm: i64,
}

impl ChunkRec {
    pub fn new(id: u32, start: u64, end: u64, conn: u32) -> Self {
        ChunkRec {
            id,
            start,
            end,
            conn,
            downloaded: 0,
            is_compl: false,
            sttm: unix_now() as i64,
            etm: 0,
        }
    }
    pub fn len(&self) -> u64 {
        self.end.saturating_sub(self.start)
    }
    pub fn remaining(&self) -> u64 {
        self.len().saturating_sub(self.downloaded)
    }
}

/// Status of a download record
/// ("Stopped", "Downloading", "Pause", "Resume", "Complete",
/// "Download complete", "Download failed").
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Status {
    /// Queued for later processing ("Download later" / in queue).
    Queued,
    /// Actively downloading.
    Downloading,
    /// Paused by user or scheduler; resumable state on disk.
    Paused,
    /// Finished and assembled.
    Complete,
    /// Terminally failed (e.g. server does not allow resume).
    Failed,
}

impl Status {
    pub fn as_str(&self) -> &'static str {
        match self {
            Status::Queued => "Queued",
            Status::Downloading => "Downloading",
            Status::Paused => "Paused",
            Status::Complete => "Complete",
            Status::Failed => "Failed",
        }
    }
}

/// A persisted download record.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DownloadRec {
    /// Numeric id (`Software\DownloadManager\<id>`; allocated via `maxID`).
    pub id: u64,
    /// Original URL (`sourceURL`).
    pub url: String,
    /// Final local path (`LocalNameForSave`).
    pub save_path: PathBuf,
    /// Known total size in bytes, 0 = unknown (`FileSize`, 8-byte registry value).
    pub file_size: u64,
    /// Whether the server supports byte ranges.
    pub resumable: bool,
    /// `ETag` observed at probe time, used with If-Range on resume.
    pub etag: Option<String>,
    /// `Last-Modified` observed at probe time (`LastModified`).
    pub last_modified: Option<String>,
    /// Segment state (`...\ChList` records).
    pub chunks: Vec<ChunkRec>,
    pub status: Status,
    /// Error text of the last failure (`lastResult`).
    pub last_error: Option<String>,
    /// Seconds of download time accumulated.
    pub downloaded_secs: u64,
    /// `dateAdded` / `lastTryDate` (unix timestamps).
    pub date_added: i64,
    pub last_try_date: i64,
    /// Queue name this download belongs to (`queueID`).
    pub queue: Option<String>,
    /// Logical group / label for organizing downloads.
    #[serde(default)]
    pub group: Option<String>,
    /// User-provided description.
    #[serde(default)]
    pub description: String,
    /// Per-download connection override (engine falls back to the
    /// global `max_connections` setting when `None`).
    #[serde(default)]
    pub max_connections: Option<u32>,
    /// Alternate mirror URLs; the engine rotates to the next one for
    /// new connections after a connection failure (IDM "Mirrors").
    #[serde(default)]
    pub mirrors: Vec<String>,
    /// Temporary part-file directory.
    pub temp_dir: PathBuf,
    /// "File size has changed on the server" restart marker.
    pub restarted: bool,
}

impl DownloadRec {
    pub fn total_downloaded(&self) -> u64 {
        self.chunks.iter().map(|c| c.downloaded).sum()
    }

    /// Directory + prefix for chunk part files of this download.
    pub fn part_prefix(&self) -> PathBuf {
        self.temp_dir.join(format!("d{}", self.id))
    }
}

/// Root persistent state: download list + settings, stored as JSON.
#[derive(Debug, Serialize, Deserialize)]
pub struct State {
    /// `Software\DownloadManager\maxID` analogue.
    pub max_id: u64,
    pub downloads: Vec<DownloadRec>,
    pub settings: Settings,
    /// Named queues (`Software\DownloadManager\Queue` analogue).
    #[serde(default)]
    pub queues: Vec<String>,
    /// Scheduler definitions (`Software\DownloadManager\Scheduler` +
    /// `%s\Scheduler\s_*.dt` analogue).
    #[serde(default)]
    pub schedules: Vec<crate::queue::Schedule>,
    /// Deleted-but-restorable downloads (Trash list).
    #[serde(default)]
    pub trash: Vec<DownloadRec>,
    /// User-defined download groups (labels).
    #[serde(default)]
    pub groups: Vec<String>,
    /// Webhook endpoints notified on task state changes.
    #[serde(default)]
    pub webhooks: Vec<Webhook>,
    /// Saved per-site credentials (auto-applied by the engine).
    #[serde(default)]
    pub site_logins: Vec<SiteLogin>,
}

impl Default for State {
    fn default() -> Self {
        State {
            max_id: 1,
            downloads: Vec::new(),
            settings: Settings::default(),
            queues: vec![crate::queue::MAIN_QUEUE.to_string()],
            schedules: Vec::new(),
            trash: Vec::new(),
            groups: Vec::new(),
            webhooks: Vec::new(),
            site_logins: Vec::new(),
        }
    }
}

/// A webhook endpoint: POSTs a JSON event body when a task changes state.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct Webhook {    /// Display name.
    pub name: String,
    /// Destination URL (http/https).
    pub url: String,
    /// Subscribed events (`started`, `completed`, `failed`, `added`).
    /// Empty = all events.
    pub events: Vec<String>,
    pub enabled: bool,
}

/// One per-site proxy route for manual proxy mode.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct AutoProxyRule {
    /// Wildcard pattern matched against the URL host (`*.example.com`).
    pub pattern: String,
    /// Proxy URL (`http://host:port`, `socks5://host:port`, `none`).
    pub proxy: String,
}

/// A saved site login (IDM "Site Login"): credentials auto-applied to
/// downloads whose URL host matches `pattern`. Stored in plain text,
/// exactly like IDM's own registry-stored credentials.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct SiteLogin {
    /// Host or `*.domain` pattern the login applies to.
    pub pattern: String,
    pub user: String,
    pub pass: String,
}

impl Default for AutoProxyRule {
    fn default() -> Self {
        AutoProxyRule { pattern: String::new(), proxy: String::new() }
    }
}

