/// "From %d:%02d to %d:%02d you downloaded %ld MB. All
/// downloads have been stopped at %d:%02d because you had exceeded your
/// download limits set in the Scheduler (or 'Options->Connections')!
/// All stopped downloads will be resumed automatically at %02d:%02d...")
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct Quota {
    /// `isLimitEnabled`
    pub enabled: bool,
    /// Megabytes allowed within the window.
    pub mb: u64,
    /// Window start hour (0-23).
    pub start_hour: u32,
    /// Window end hour (0-23).
    pub end_hour: u32,
}

impl Default for Quota {
    fn default() -> Self {
        Quota { enabled: false, mb: 500, start_hour: 0, end_hour: 23 }
    }
}

/// Proxy configuration (per-protocol `HttpProxy`, `FtpProxy`,
/// `HttpsProxy`, plus `socks4://` / `socks5://` URLs, `SocksHost/Port`).
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct Proxies {
    pub http: Option<String>,
    pub https: Option<String>,
    pub ftp: Option<String>,
    pub user: Option<String>,
    pub password: Option<String>,
}

impl Default for Proxies {
    fn default() -> Self {
        Proxies { http: None, https: None, ftp: None, user: None, password: None }
    }
}

